/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import re
expected={'shop.example.com':16,'blog.example.com':17,'dept.company.com':18,'intranet.company.com':19,'api.service.com':20,'ai.research.lab.net':22,'data.research.lab.net':23,'dev.lab.net':24,'ci.tools.net':25,'vpn.university.edu':26,'courses.university.edu':27,'portal.campus.edu':28,'studenti.unibo.it':29,'servizi.comune.it':30,'dati.regione.it':31,'mail.company.com':7,'mail.university.edu':11}
found={}
for p in Path('pc1/etc/bind/lab').glob('db.*'):
    zone=p.name[3:]
    for line in p.read_text().splitlines():
        fields=line.split()
        if len(fields)==4 and fields[1:3]==['IN','A']:
            found[f'{fields[0]}.{zone}']=fields[3]
for name,pc in expected.items():
    address=re.search(r'inet (10\\.\\d+\\.\\d+\\.\\d+)/24',Path(f'pc{pc}.startup').read_text()).group(1)
    assert found.get(name)==address,(name,address,found.get(name))
for zone in ('company.com','university.edu'):
    assert f'@ IN MX 10 mail.{zone}.' in Path(f'pc1/etc/bind/lab/db.{zone}').read_text()
for pc in range(1,41):
    assert 'nameserver 10.15.1.11' in Path(f'pc{pc}.startup').read_text()
print('Verified 17 host records, 2 MX records, and DNS configuration on 40 PCs.')
PY"

